def concatenated_words(words):
    class Node:
        __slots__ = ("children", "is_word")

        def __init__(self):
            self.children = {}
            self.is_word = False

    root = Node()
    for w in words:
        node = root
        for ch in w:
            node = node.children.setdefault(ch, Node())
        node.is_word = True

    def can_form(word, start, pieces):
        node = root
        n = len(word)
        for i in range(start, n):
            ch = word[i]
            if ch not in node.children:
                return False
            node = node.children[ch]
            if node.is_word:
                if i + 1 == n:
                    return pieces >= 1
                if can_form(word, i + 1, pieces + 1):
                    return True
        return False

    result = [w for w in words if w and can_form(w, 0, 0)]
    return sorted(result)
